+        match &refreshed.kind {
+            InodeKind::File { file_meta_resolved, .. } => {
+                assert!(
+                    !*file_meta_resolved,
+                    "Regression guard: changed mtime must still force re-resolution"
+                );
+            }
+            _ => panic!("Expected File kind"),
+        }
+    }
